    public function getSourceContext(): Source
    {
        return new Source("{% extends 'base.html.twig' %}

{% block title %}Register{% endblock %}

{% block body %}
    <div class=\"container d-flex justify-content-center mt-5 vh-100\">
        <div class=\"card p-4 shadow\" style=\"width: 400px; height: 655px;\">
            <h1 class=\"text-center\">Register</h1>

            {{ form_errors(registrationForm) }}

            {{ form_start(registrationForm) }}
               <div class=\"mb-3\">
                    {{ form_row(registrationForm.username, {
                        label: 'username',
                        attr: { class: 'form-control' }
                    }) }}
                </div>  
                <div class=\"mb-3\">
                    {{ form_row(registrationForm.firstname, {
                        label: 'First Name',
                        attr: { class: 'form-control' }
                    }) }}
                </div>
                <div class=\"mb-3\">
                    {{ form_row(registrationForm.lastname, {
                        label: 'Last Name',
                        attr: { class: 'form-control' }
                    }) }}
                </div>
                <div class=\"mb-3 \">
                    {{ form_row(registrationForm.biographie, {
                        attr: { class: 'form-control' }
                    }) }}
                </div>
                <div class=\"mb-3\">
                    {{ form_row(registrationForm.email, {
                        attr: { class: 'form-control' }
                    }) }}
                </div>
                <div class=\"mb-3\">
                    {{ form_row(registrationForm.plainPassword, {
                        label: 'Password',
                        attr: { class: 'form-control' }
                    }) }}
                </div>
                <div class=\"mb-3 form-check\">
                    {{ form_row(registrationForm.agreeTerms, {
                        attr: { class: 'form-check-input' }
                    }) }}
                </div>

                <button type=\"submit\" class=\"btn btn-primary w-100\">Register</button>
            {{ form_end(registrationForm) }}
        </div>
    </div>
{% endblock %}", "registration/register.html.twig", "/home/adel/dev/ProjectHub/templates/registration/register.html.twig");
